<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_AI_Assistant{
 public static function init():void{add_action('rest_api_init',[self::class,'routes']);}
 public static function routes():void{register_rest_route('nvconsult/v1','/ai/case-summary',['methods'=>WP_REST_Server::CREATABLE,'callback'=>[self::class,'summary'],'permission_callback'=>static fn()=>current_user_can('nvconsult_manage_applications'),'args'=>['application_id'=>['required'=>true,'sanitize_callback'=>'absint']]]);}
 public static function summary(WP_REST_Request$r){$id=absint($r['application_id']);if(get_post_type($id)!=='nv_application')return new WP_Error('invalid_application',__('Invalid application.','nvconsult-core'),['status'=>404]);$uid=get_current_user_id();$rl='nvc_ai_'.$uid;if((int)get_transient($rl)>=20)return new WP_Error('ai_rate_limit',__('AI request limit reached. Please retry later.','nvconsult-core'),['status'=>429]);set_transient($rl,(int)get_transient($rl)+1,HOUR_IN_SECONDS);$key=getenv('OPENAI_API_KEY');if(!$key)return new WP_Error('ai_not_configured',__('AI is not configured. Set OPENAI_API_KEY on the server.','nvconsult-core'),['status'=>503]);$status=(string)get_post_meta($id,'_nvconsult_status',true);$type=(string)get_post_meta($id,'_nvconsult_application_type',true);$activity=array_slice(NVConsult_Core_Activity::items($id,true),0,15);$safe=[];foreach($activity as$i){if(in_array($i['type'],['message','document'],true))$text=$i['type']==='message'?__('Message activity recorded','nvconsult-core'):__('Document activity recorded','nvconsult-core');else $text=mb_substr(wp_strip_all_tags((string)$i['text']),0,500);$safe[]=['type'=>$i['type'],'text'=>$text,'time'=>$i['time']];}$prompt="Summarize this consultancy case for authorized staff. Do not invent facts or provide legal conclusions. Identify current status, pending actions, operational risks, and a recommended next administrative step.\nType: ".$type."\nStatus: ".$status."\nRecent activity: ".wp_json_encode($safe);$body=['model'=>apply_filters('nvconsult_openai_model','gpt-5-mini'),'input'=>$prompt,'max_output_tokens'=>500];$res=wp_remote_post('https://api.openai.com/v1/responses',['timeout'=>45,'headers'=>['Authorization'=>'Bearer '.$key,'Content-Type'=>'application/json'],'body'=>wp_json_encode($body)]);if(is_wp_error($res))return new WP_Error('ai_transport_error',__('AI service could not be reached.','nvconsult-core'),['status'=>502]);$code=wp_remote_retrieve_response_code($res);$data=json_decode(wp_remote_retrieve_body($res),true);if($code<200||$code>=300)return new WP_Error('openai_error',__('AI request failed.','nvconsult-core'),['status'=>502]);$text='';foreach(($data['output']??[])as$o)foreach(($o['content']??[])as$c)if(($c['type']??'')==='output_text')$text.=(string)($c['text']??'');$text=trim($text);if(!$text)return new WP_Error('empty_ai_response',__('AI returned no summary.','nvconsult-core'),['status'=>502]);add_post_meta($id,'_nvconsult_history',['type'=>'ai','message'=>__('AI case summary generated by staff.','nvconsult-core'),'time'=>current_time('mysql'),'user_id'=>$uid]);return rest_ensure_response(['summary'=>$text,'generated_at'=>current_time(DATE_ATOM)]);}
}
